    parking_control_a5_->set_parking_target(
        Parking_control_a5::PARKING_TARGET_PARKING_TRIGGER);
  } else {
    parking_control_a5_->set_parking_target(
        Parking_control_a5::PARKING_TARGET_RELEASE);
  }
}

