double ComputeCartesianDeviationY(const double s) const {
  auto sin_theta = [this](const double s) {
    const auto a = Evaluate(0, s);
    return std::sin(a);
  };
  return common::math::IntegrateByGaussLegendre<N>(sin_theta, 0.0, s);
}

