template <typename T>
bool IsCoveredVertical(const base::Rect<T> &rect1, const base::Rect<T> &rect2,
                       float thresh) {
  base::RectF inter = rect1 & rect2;
  if (inter.Area() > 0) {
    return inter.height / rect1.height > thresh;
  }
  return false;
}

