template <typename T>
inline void IMultABt2x3And2x3(const T A[6], const T B[6], T ABt[4]) {
  ABt[0] = A[0] * B[0] + A[1] * B[1] + A[2] * B[2];
  ABt[1] = A[0] * B[3] + A[1] * B[4] + A[2] * B[5];
  ABt[2] = A[3] * B[0] + A[4] * B[1] + A[5] * B[2];
