inline void IMultAtx4x3(const T A[12], const T x[3], T Atx[4]) {
  Atx[0] = A[0] * x[0] + A[4] * x[1] + A[8] * x[2];
  Atx[1] = A[1] * x[0] + A[5] * x[1] + A[9] * x[2];
  Atx[2] = A[2] * x[0] + A[6] * x[1] + A[10] * x[2];
  Atx[3] = A[3] * x[0] + A[7] * x[1] + A[11] * x[2];
}
