bool LRUCache<Key, Element>::IsExist(const Key &key) {
  MapIterator found_iter = map_.find(key);
  if (found_iter != map_.end()) {
    list_.splice(list_.begin(), list_, found_iter->second);
  }
  return found_iter != map_.end();
}

