inline void IMultAB2x3And3x3(const T A[6], const T B[9], T AB[6]) {
  T a, b, c;
  a = A[0];
  b = A[1];
  c = A[2];
  AB[0] = a * B[0] + b * B[3] + c * B[6];
  AB[1] = a * B[1] + b * B[4] + c * B[7];
  AB[2] = a * B[2] + b * B[5] + c * B[8];

