inline void ICentroid3(const double *a, int n, double centroid[3]) {
  int length = 3 * n;
  IFill3(centroid, 0.0);
  for (int i = 0; i < length; i += 3) {
    IAdd3(a + i, centroid);
  }
  IScale3(centroid, IRec(n));
}
inline void ICentroid3(const float *a, int n, float centroid[3]) {
