inline void IInvert3x3UpperTriangular(const float A[9], float Ai[9]) {
  float A4A8 = A[4] * A[8];
  float A0rec = IRec(A[0]);
  Ai[0] = A0rec;
  Ai[1] = -IDiv(A[1], A[0] * A[4]);
  Ai[2] = (IDiv(A[1] * A[5], A4A8) - IDiv(A[2], A[8])) * A0rec;
  Ai[3] = 0;
  Ai[4] = IRec(A[4]);
  Ai[5] = -IDiv(A[5], A4A8);
  Ai[6] = 0;
  Ai[7] = 0;
  Ai[8] = IRec(A[8]);
}
