int32_t Brake61::watchdog_counter_source(const std::uint8_t *bytes,
                                         int32_t length) const {
  // see table for status code
  Byte frame(bytes + 6);

const double reference_line_fence_s =
    adc_sl_boundary_.end_s() + obstacle_boundary.min_s() + yield_distance_s;
const double main_stop_s =
    reference_line_info_->path_decision()->stop_reference_line_s();
if (main_stop_s < reference_line_fence_s) {
  ADEBUG << "Yield reference_s is further away, ignore.";
  return false;
}

auto ref_point = reference_line_->GetReferencePoint(reference_line_fence_s);

// set YIELD decision
auto* yield = yield_decision->mutable_yield();
yield->set_distance_s(yield_distance_s);
yield->mutable_fence_point()->set_x(ref_point.x());
yield->mutable_fence_point()->set_y(ref_point.y());
yield->mutable_fence_point()->set_z(0.0);
yield->set_fence_heading(ref_point.heading());

std::vector<double> ego_vehicle_feature_values;
SetEgoVehicleFeatureValues(obstacle_ptr, &ego_vehicle_feature_values);
if (ego_vehicle_feature_values.size() != EGO_VEHICLE_FEATURE_SIZE) {
  AERROR << "Obstacle [" << id << "] has fewer than "
         << "expected ego vehicle feature_values"
         << ego_vehicle_feature_values.size() << ".";
  return;
}

std::vector<double> junction_feature_values;
SetJunctionFeatureValues(obstacle_ptr, &junction_feature_values);
if (junction_feature_values.size() != JUNCTION_FEATURE_SIZE) {
  AERROR << "Obstacle [" << id << "] has fewer than "
         << "expected junction feature_values"
         << junction_feature_values.size() << ".";
  return;

