bool OfflineLocalVisualizer::GnssLocFileHandler(
    const std::vector<double> &pcd_timestamps) {
  std::vector<Eigen::Affine3d> poses;
  std::vector<Eigen::Vector3d> stds;
  std::vector<double> timestamps;
  velodyne::LoadPosesAndStds(gnss_loc_file_, &poses, &stds, &timestamps);

  PoseAndStdInterpolationByTime(poses, stds, timestamps, pcd_timestamps,
                                &gnss_poses_, &gnss_stds_);

  return true;
}

bool OfflineLocalVisualizer::FusionLocFileHandler(
    const std::vector<double> &pcd_timestamps) {
  std::vector<Eigen::Affine3d> poses;
  std::vector<Eigen::Vector3d> stds;
  std::vector<double> timestamps;
  velodyne::LoadPosesAndStds(fusion_loc_file_, &poses, &stds, &timestamps);

  PoseAndStdInterpolationByTime(poses, stds, timestamps, pcd_timestamps,
                                &fusion_poses_, &fusion_stds_);
  return true;

  if (nsent < 0) {  // error
    if (errno == EINTR) {
      continue;
    } else {
      // error
      if (errno == EPIPE || errno == ECONNRESET) {
        status_ = Stream::Status::DISCONNECTED;
        errno_ = errno;
      } else if (errno != EAGAIN) {
        status_ = Stream::Status::ERROR;
        errno_ = errno;
      }
      return total_nsent;
    }
  }

  total_nsent += nsent;
  length -= nsent;
  data += nsent;
}

return total_nsent;

template <typename DATA_TYPE>
bool VoxelGridXYPyramid<DATA_TYPE>::SetS(const float *pc,
                                         unsigned int nr_points,
                                         unsigned int nr_point_element) {
  if (!pc || !nr_points || !nr_point_element || vgrids_.empty()) {
    return false;
  }

  unsigned int scale, nr_scale = (unsigned int)vgrids_.size();

  pc_ = pc;
  nr_points_ = nr_points;
  nr_point_element_ = nr_point_element;

  for (scale = 0; scale < nr_scale; ++scale) {
    if (!vgrids_[scale].set_s(pc, nr_points, nr_point_element)) {
      break;
    }
  }

  // break in the middle - last (NrScale - s) grids are invalid
  if (scale < nr_scale) {
    vgrids_.resize(scale);
  }

  return (vgrids_.size() == nr_scale);
}

