inline int IMinAbsIndexIntervalColumn(const float *a, int i1, int i2, int n) {
  int bi;
  float b, t;
  const float *ref = a + i1 * n;
  b = IAbs(*ref);
  bi = i1;
  for (int i = i1 + 1; i < i2; ++i, ref += n) {
    if ((t = IAbs(*ref)) < b) {
      b = t;
      bi = i;
    }
  }
  return (bi);
}
