// '%'}
double Llcmotioncommandfeedback122::llc_fbk_throttlesetpoint(
    const std::uint8_t* bytes, int32_t length) const {
  Byte t0(bytes + 2);
  int32_t x = t0.get_byte(0, 5);

  Byte t1(bytes + 1);
  int32_t t = t1.get_byte(3, 5);
  x <<= 5;
  x |= t;

  double ret = x * 0.100000;
  return ret;

double Steering65::steering_angle(const std::uint8_t *bytes,
                                  int32_t length) const {
  Byte frame_high(bytes + 1);
  int32_t high = frame_high.get_byte(0, 8);
  Byte frame_low(bytes + 0);
  int32_t low = frame_low.get_byte(0, 8);
  int32_t value = (high << 8) | low;
  if (value > 0x8000) {
    value = value - 0x10000;
  }

  return value * 0.100000;
}

double Steering65::reported_steering_angle_cmd(const std::uint8_t *bytes,
                                               int32_t length) const {
  Byte frame_high(bytes + 3);
  int32_t high = frame_high.get_byte(0, 8);
  Byte frame_low(bytes + 2);
  int32_t low = frame_low.get_byte(0, 8);
  int32_t value = (high << 8) | low;

SingleLanePredictor::SingleLanePredictor() {
  predictor_type_ = ObstacleConf::SINGLE_LANE_PREDICTOR;
}

void SingleLanePredictor::Predict(Obstacle* obstacle) {
  Clear();

  CHECK_NOTNULL(obstacle);
  CHECK_GT(obstacle->history_size(), 0);

  obstacle->SetPredictorType(predictor_type_);

  const Feature& feature = obstacle->latest_feature();

  if (!feature.has_lane() || !feature.lane().has_lane_graph()) {
    AERROR << "Obstacle [" << obstacle->id() << "] has no lane graph.";
    return;
  }

  std::string lane_id = "";
  if (feature.lane().has_lane_feature()) {
    lane_id = feature.lane().lane_feature().lane_id();
  }
  int num_lane_sequence = feature.lane().lane_graph().lane_sequence_size();

bool use_hotstart =
    last_problem_success_ &&
    (FLAGS_enable_sqp_solver && sqp_solver_ != nullptr &&
     num_param == last_num_param_ && num_constraint == last_num_constraint_);

if (!use_hotstart) {
  sqp_solver_.reset(new ::qpOASES::SQProblem(num_param, num_constraint,
                                             ::qpOASES::HST_UNKNOWN));
  ::qpOASES::Options my_options;
  my_options.enableCholeskyRefactorisation = 10;
  my_options.epsNum = FLAGS_default_qp_smoothing_eps_num;
  my_options.epsDen = FLAGS_default_qp_smoothing_eps_den;
  my_options.epsIterRef = FLAGS_default_qp_smoothing_eps_iter_ref;
  sqp_solver_->setOptions(my_options);
  if (!FLAGS_default_enable_active_set_debug_info) {
    sqp_solver_->setPrintLevel(qpOASES::PL_NONE);
  }
}

