// config detail: {'name': 'raw_pedal_pos_is_valid', 'offset': 0.0,
// 'precision': 1.0, 'len': 1, 'is_signed_var': False, 'physical_range':
// '[0|1]', 'bit': 40, 'type': 'bool', 'order': 'motorola', 'physical_unit': ''}
bool Accelauxrpt300::raw_pedal_pos_is_valid(const std::uint8_t* bytes,
                                            int32_t length) const {
  Byte t0(bytes + 5);
  int32_t x = t0.get_byte(0, 1);

  bool ret = x;
  return ret;
}

// config detail: {'name': 'raw_pedal_pos', 'offset': 0.0, 'precision': 0.001,
// 'len': 16, 'is_signed_var': True, 'physical_range': '[-32.768|32.767]',
// 'bit': 7, 'type': 'double', 'order': 'motorola', 'physical_unit': ''}
double Accelauxrpt300::raw_pedal_pos(const std::uint8_t* bytes,
                                     int32_t length) const {
  Byte t0(bytes + 0);
  int32_t x = t0.get_byte(0, 8);

  Byte t1(bytes + 1);
  int32_t t = t1.get_byte(0, 8);
  x <<= 8;
  x |= t;

  x <<= 16;
  x >>= 16;

  double ret = x * 0.001000;
  return ret;

int time_index = time_start_index_;
int state_index = state_start_index_;

// TODO(QiL): Initial implementation towards earlier understanding and debug
// purpose, later code refine towards improving efficiency

*obj_value = 0.0;
// 1. objective to minimize state diff to warm up
for (int i = 0; i < horizon_ + 1; ++i) {
  T x1_diff = x[state_index] - xWS_(0, i);
  T x2_diff = x[state_index + 1] - xWS_(1, i);
  T x3_diff = x[state_index + 2] - xWS_(2, i);
  T x4_abs = x[state_index + 3];
  *obj_value += weight_state_x_ * x1_diff * x1_diff +
                weight_state_y_ * x2_diff * x2_diff +
                weight_state_phi_ * x3_diff * x3_diff +
                weight_state_v_ * x4_abs * x4_abs;
  state_index += 4;
}

// 2. objective to minimize u square
for (int i = 0; i < horizon_; ++i) {
  *obj_value += weight_input_steer_ * x[control_index] * x[control_index] +
                weight_input_a_ * x[control_index + 1] * x[control_index + 1];
  control_index += 2;
}

// 3. objective to minimize input change rate for first horizon
control_index = control_start_index_;

void SubTopoGraph::AddPotentialInEdge(
    TopoNode* const sub_node,
    const std::unordered_set<const TopoEdge*> origin_edge) {
  std::unordered_set<TopoNode*> other_sub_nodes;
  for (const auto* in_edge : origin_edge) {
    if (GetSubNodes(in_edge->FromNode(), &other_sub_nodes)) {
      for (auto* sub_from_node : other_sub_nodes) {
        if (sub_node->GetInEdgeFrom(sub_from_node) != nullptr) {
          continue;
        }
        if (!IsReachable(sub_from_node, sub_node)) {
          continue;
        }
        std::shared_ptr<TopoEdge> topo_edge_ptr;
        topo_edge_ptr.reset(
            new TopoEdge(in_edge->PbEdge(), sub_from_node, sub_node));
        sub_node->AddInEdge(topo_edge_ptr.get());
        sub_from_node->AddOutEdge(topo_edge_ptr.get());
        topo_edges_.push_back(std::move(topo_edge_ptr));
      }
    } else {
      if (sub_node->GetInEdgeFrom(in_edge->FromNode()) != nullptr) {
        continue;
      }
      std::shared_ptr<TopoEdge> topo_edge_ptr;

    AINFO << "Need to check response again.";
  } while (need_wait && retry_num);

  AINFO << "check_response fail: is_eps_online: " << is_eps_online
        << ", is_vcu_online: " << is_vcu_online
        << ", is_esp_online: " << is_esp_online;
  return false;
}

