void GemController::SecurityDogThreadFunc() {
  int32_t vertical_ctrl_fail = 0;
  int32_t horizontal_ctrl_fail = 0;

  if (can_sender_ == nullptr) {
    AERROR << "Failed to run SecurityDogThreadFunc() because can_sender_ is "
              "nullptr.";
    return;
  }
  while (!can_sender_->IsRunning()) {
    std::this_thread::yield();
  }

  std::chrono::duration<double, std::micro> default_period{50000};
  int64_t start = 0;
  int64_t end = 0;
  while (can_sender_->IsRunning()) {
    start = ::apollo::common::time::AsInt64<::apollo::common::time::micros>(
        ::apollo::common::time::Clock::Now());
    const Chassis::DrivingMode mode = driving_mode();
    bool emergency_mode = false;

  ++nz_index;
}

// With respect to n
iRow[nz_index] = constraint_index + 1;
jCol[nz_index] = n_index + 1;
++nz_index;

iRow[nz_index] = constraint_index + 1;
jCol[nz_index] = n_index + 3;
++nz_index;

// 3. -g'*mu + (A*t - b)*lambda > 0
// with respect to l
for (int k = 0; k < current_edges_num; ++k) {
  iRow[nz_index] = constraint_index + 2;
  jCol[nz_index] = l_index + k;
  ++nz_index;
}

// with respect to n
for (int k = 0; k < 4; ++k) {
  iRow[nz_index] = constraint_index + 2;
  jCol[nz_index] = n_index + k;
  ++nz_index;
}

// Update index
l_index += current_edges_num;
n_index += 4;
constraint_index += 3;

