// config detail: {'description': 'Indicates Lateral Acceleration', 'offset':
// -21.592, 'precision': 0.00098, 'len': 16, 'name': 'lateralacce',
// 'is_signed_var': False, 'physical_range': '[-21.592|21.592]', 'bit': 23,
// 'type': 'double', 'order': 'motorola', 'physical_unit': 'm/s^2'}
double Fbs1243::lateralacce(const std::uint8_t* bytes, int32_t length) const {
  Byte t0(bytes + 2);
  int32_t x = t0.get_byte(0, 8);

  Byte t1(bytes + 3);
  int32_t t = t1.get_byte(0, 8);
  x <<= 8;
  x |= t;

  double ret = x * 0.000980 + -21.592000;
  return ret;
}

// config detail: {'description': 'Vehicle yaw rate', 'offset': -2.093,
// 'precision': 0.00024, 'len': 16, 'name': 'vehdynyawrate', 'is_signed_var':
// False, 'physical_range': '[-2.093|2.093]', 'bit': 39, 'type': 'double',
// 'order': 'motorola', 'physical_unit': 'rad/s'}
double Fbs1243::vehdynyawrate(const std::uint8_t* bytes, int32_t length) const {
  Byte t0(bytes + 4);
  int32_t x = t0.get_byte(0, 8);

  Byte t1(bytes + 5);
  int32_t t = t1.get_byte(0, 8);
  x <<= 8;
  x |= t;

  double ret = x * 0.000240 + -2.093000;
  return ret;

void PullOverScenario::RegisterStages() {
  if (!s_stage_factory_.Empty()) {
    s_stage_factory_.Clear();
  }
  s_stage_factory_.Register(
      ScenarioConfig::PULL_OVER_APPROACH,
      [](const ScenarioConfig::StageConfig& config) -> Stage* {
        return new PullOverStageApproach(config);
      });
  s_stage_factory_.Register(
      ScenarioConfig::PULL_OVER_RETRY_APPROACH_PARKING,
      [](const ScenarioConfig::StageConfig& config) -> Stage* {
        return new PullOverStageRetryApproachParking(config);
      });
  s_stage_factory_.Register(
      ScenarioConfig::PULL_OVER_RETRY_PARKING,
      [](const ScenarioConfig::StageConfig& config) -> Stage* {
        return new PullOverStageRetryParking(config);
      });
}

std::unique_ptr<Stage> PullOverScenario::CreateStage(
    const ScenarioConfig::StageConfig& stage_config) {
  if (s_stage_factory_.Empty()) {
    RegisterStages();
  }
  auto ptr = s_stage_factory_.CreateObjectOrNull(stage_config.stage_type(),
                                                 stage_config);
  if (ptr) {
    ptr->SetContext(&context_);
  }
  return ptr;
}

/*
 * read scenario specific configs and set in context_ for stages to read
 */
bool PullOverScenario::GetScenarioConfig() {
  if (!config_.has_pull_over_config()) {
    AERROR << "miss scenario specific config";
    return false;
  }
  context_.scenario_config.CopyFrom(config_.pull_over_config());
  return true;

