bool RTKLocalization::FindNearestGpsStatus(const double gps_timestamp_sec,
                                           drivers::gnss::InsStat *status) {
  CHECK_NOTNULL(status);

  std::unique_lock<std::mutex> lock(gps_status_list_mutex_);
  auto gps_status_list = gps_status_list_;
  lock.unlock();

  double timestamp_diff_sec = 1e8;
  auto nearest_itr = gps_status_list.end();
  for (auto itr = gps_status_list.begin(); itr != gps_status_list.end();
       ++itr) {
    double diff = std::abs(itr->header().timestamp_sec() - gps_timestamp_sec);
    if (diff < timestamp_diff_sec) {
      timestamp_diff_sec = diff;
      nearest_itr = itr;
    }
  }

  if (nearest_itr == gps_status_list.end()) {
    return false;
  }

  if (timestamp_diff_sec > gps_status_time_diff_threshold_) {
    return false;
  }

  *status = *nearest_itr;
  return true;

int l_index = l_start_index_;
int n_index = n_start_index_;

for (int i = 0; i < horizon_ + 1; ++i) {
  int edges_counter = 0;
  for (int j = 0; j < obstacles_num_; ++j) {
    int current_edges_num = obstacles_edges_num_(j, 0);
    Eigen::MatrixXd Aj =
        obstacles_A_.block(edges_counter, 0, current_edges_num, 2);
    Eigen::MatrixXd bj =
        obstacles_b_.block(edges_counter, 0, current_edges_num, 1);

    // TODO(QiL) : Remove redundant calculation
    double tmp1 = 0;
    double tmp2 = 0;
    for (int k = 0; k < current_edges_num; ++k) {
      // TODO(QiL) : replace this one directly with x
      tmp1 += Aj(k, 0) * x[l_index + k];
      tmp2 += Aj(k, 1) * x[l_index + k];
    }

    // 1. norm(A* lambda == 1)
    for (int k = 0; k < current_edges_num; ++k) {
      // with respect to l
      values[nz_index] =
          2 * tmp1 * Aj(k, 0) + 2 * tmp2 * Aj(k, 1);  // t0~tk
      ++nz_index;

  return ret;
}

