      default_object_width = FLAGS_default_car_width;
      break;
    }
    case 1: {
      default_object_width = FLAGS_default_truck_width;
      break;
    }
    case 2: {
      default_object_width = FLAGS_default_bike_width;
      break;
    }
    case 3: {
      default_object_width = FLAGS_default_ped_width;
      break;
    }
    case 4: {
      default_object_width = FLAGS_default_unknown_width;
      break;
    }
  }
  return default_object_width;

  return Status::OK();
}

Status SignalsXmlParser::ParseYieldSigns(
    const tinyxml2::XMLElement& xml_node,
    std::vector<YieldSignInternal>* yield_signs) {
  CHECK_NOTNULL(yield_signs);

  auto signal_node = xml_node.FirstChildElement("signal");
  while (signal_node) {
    std::string object_type;
    std::string object_id;
    int checker =
        UtilXmlParser::QueryStringAttribute(*signal_node, "type", &object_type);
    checker +=
        UtilXmlParser::QueryStringAttribute(*signal_node, "id", &object_id);
    if (checker != tinyxml2::XML_SUCCESS) {
      std::string err_msg = "Error parse signal type.";
      return Status(apollo::common::ErrorCode::HDMAP_DATA_ERROR, err_msg);
    }

    if (object_type == "yieldSign") {
      PbYieldSign yield_sign;
      yield_sign.mutable_id()->set_id(object_id);
      YieldSignInternal yield_sign_internal;
      yield_sign_internal.id = object_id;

(*speed_profile_properties)["borderWidth"] = "2";
(*speed_profile_properties)["pointRadius"] = "0";
(*speed_profile_properties)["lineTension"] = "0";
(*speed_profile_properties)["fill"] = "false";
(*speed_profile_properties)["showLine"] = "true";

auto* sliding_line = chart->add_line();
sliding_line->set_label("Time");

auto* point_debug_up = sliding_line->add_point();
point_debug_up->set_x(Clock::NowInSeconds());
point_debug_up->set_y(2.1);
auto* point_debug_down = sliding_line->add_point();
point_debug_down->set_x(Clock::NowInSeconds());
point_debug_down->set_y(-1.1);

// Set chartJS's dataset properties
auto* sliding_line_properties = sliding_line->mutable_properties();
(*sliding_line_properties)["borderWidth"] = "2";
(*sliding_line_properties)["pointRadius"] = "0";
(*sliding_line_properties)["lineTension"] = "0";
(*sliding_line_properties)["fill"] = "false";
(*sliding_line_properties)["showLine"] = "true";

  for (const auto &camera_name : camera_names_) {
    float height = 0.0f;
    SetCameraHeight(camera_name, FLAGS_obs_sensor_intrinsic_path,
                    default_camera_height_, &height);
    camera_height_map_[camera_name] = height;
  }

  for (auto &frame : camera_frames_) {
    frame.track_feature_blob.reset(new base::Blob<float>());
    frame.lane_detected_blob.reset(new base::Blob<float>());
  }
  return cyber::SUCC;
}

int LaneDetectionComponent::InitProjectMatrix() {
  if (!GetProjectMatrix(camera_names_, extrinsic_map_, intrinsic_map_,
                        &project_matrix_, &pitch_diff_)) {
    AERROR << "GetProjectMatrix failed";
    return cyber::FAIL;
  }
  AINFO << "project_matrix_: " << project_matrix_;
  AINFO << "pitch_diff_:" << pitch_diff_;
  name_camera_pitch_angle_diff_map_[camera_names_[0]] = 0.f;
  name_camera_pitch_angle_diff_map_[camera_names_[1]] =
      static_cast<float>(pitch_diff_);

  return cyber::SUCC;
}

