template <class T>
T* DisjointSetFind(T* x) {
  T* y = x->parent;
  if (y == x || y->parent == y) {
    return y;
  }
  T* root = DisjointSetFindLoop(y->parent);
  x->parent = root;
  y->parent = root;
  return root;
}

