// config detail: {'name': 'torque_input', 'offset': 0.0, 'precision': 0.001,
// 'len': 32, 'is_signed_var': True, 'physical_range':
// '[-2147483.648|2147483.647]', 'bit': 39, 'type': 'double', 'order':
// 'motorola', 'physical_unit': 'N-m'}
double Steeringmotorrpt3406::torque_input(const std::uint8_t* bytes,
                                          int32_t length) const {
  Byte t0(bytes + 4);
  int32_t x = t0.get_byte(0, 8);

  Byte t1(bytes + 5);
  int32_t t = t1.get_byte(0, 8);
  x <<= 8;
  x |= t;

  Byte t2(bytes + 6);
  t = t2.get_byte(0, 8);
  x <<= 8;
  x |= t;

  Byte t3(bytes + 7);
  t = t3.get_byte(0, 8);
  x <<= 8;
  x |= t;

  x <<= 0;
  x >>= 0;

  double ret = x * 0.001000;
  return ret;

T mat_a[9], eigv[3], mat_q[9];
// compute the centroid of input Data points
T xm = static_cast<T>(0.0);
T ym = static_cast<T>(0.0);
T zm = static_cast<T>(0.0);
for (i = 0, j = 0; i < n; i++) {
  xm += X[j++];
  ym += X[j++];
  zm += X[j++];
}
xm /= n;
ym /= n;
zm /= n;
for (i = 0, j = 0; i < n; i++) {
  X[j++] -= xm;
  X[j++] -= ym;
  X[j++] -= zm;
}
IMultAtANx3(X, mat_a, n);
IEigSymmetric3x3Closed(mat_a, eigv, mat_q);
// pi's normal vector is the eigen vector of
// mat_a corresponding to its smallest eigen value
pi[0] = mat_q[2];
pi[1] = mat_q[5];
pi[2] = mat_q[8];

  return 0;
}

int HDMapImpl::GetStopSignAssociatedLanes(
    const Id& id, std::vector<LaneInfoConstPtr>* lanes) const {
  CHECK_NOTNULL(lanes);

  const auto& stop_sign = GetStopSignById(id);
  if (stop_sign == nullptr) {
    return -1;
  }

  std::vector<Id> associate_stop_sign_ids;
  const auto junction_ids = stop_sign->OverlapJunctionIds();
  for (const auto& junction_id : junction_ids) {
    const auto& junction = GetJunctionById(junction_id);
    if (junction == nullptr) {
      continue;
    }
    const auto stop_sign_ids = junction->OverlapStopSignIds();
    std::copy(stop_sign_ids.begin(), stop_sign_ids.end(),
              std::back_inserter(associate_stop_sign_ids));
  }

  std::vector<Id> associate_lane_ids;
  for (const auto& stop_sign_id : associate_stop_sign_ids) {
    if (stop_sign_id.id() == id.id()) {
      // exclude current stop sign
      continue;
    }
    const auto& stop_sign = GetStopSignById(stop_sign_id);
    if (stop_sign == nullptr) {
      continue;

  Byte t0(bytes + 4);
  int32_t x = t0.get_byte(0, 8);

  Vehicle_state_feedback_c1::Gear_state_actualType ret =
      static_cast<Vehicle_state_feedback_c1::Gear_state_actualType>(x);
  return ret;
}

