bool Spline1dConstraint::AddThirdDerivativeSmoothConstraint() {
  if (x_knots_.size() < 3) {
    return false;
  }

  const uint32_t n_constraint =
      (static_cast<uint32_t>(x_knots_.size()) - 2) * 4;
  const uint32_t num_params = spline_order_ + 1;
  Eigen::MatrixXd equality_constraint =
      Eigen::MatrixXd::Zero(n_constraint, (x_knots_.size() - 1) * num_params);
  Eigen::MatrixXd equality_boundary = Eigen::MatrixXd::Zero(n_constraint, 1);

  for (uint32_t i = 0; i < n_constraint; i += 4) {
    double left_coef = 1.0;
    double right_coef = -1.0;
    double left_dcoef = 1.0;
    double right_dcoef = -1.0;
    double left_ddcoef = 1.0;
    double right_ddcoef = -1.0;

  double gps_seconds;     // seconds of week
  double latitude;        // in degrees
  double longitude;       // in degrees
  double height;          // Ellipsoidal height - WGS84 (m)
  double north_velocity;  // velocity in a northerly direction (m/s)
  double east_velocity;   // velocity in an easterly direction (m/s)
  double up_velocity;     // velocity in an up direction
  double roll;            // right handed rotation around y-axis (degrees)
  double pitch;           // right handed rotation around x-axis (degrees)
  double azimuth;         // left handed rotation around z-axis (degrees)
  InsStatus status;       // status of the INS system
};
