  chassis->mutable_lexus()->mutable_media_controls_rpt_220()->set_output_value(
      output_value(bytes, length));
  chassis->mutable_lexus()
      ->mutable_media_controls_rpt_220()
      ->set_commanded_value(commanded_value(bytes, length));
  chassis->mutable_lexus()->mutable_media_controls_rpt_220()->set_manual_input(
      manual_input(bytes, length));
  chassis->mutable_lexus()->mutable_media_controls_rpt_220()->set_vehicle_fault(
      vehicle_fault(bytes, length));
  chassis->mutable_lexus()->mutable_media_controls_rpt_220()->set_pacmod_fault(
      pacmod_fault(bytes, length));
  chassis->mutable_lexus()
      ->mutable_media_controls_rpt_220()
      ->set_override_active(override_active(bytes, length));
  chassis->mutable_lexus()
      ->mutable_media_controls_rpt_220()
      ->set_output_reported_fault(output_reported_fault(bytes, length));
  chassis->mutable_lexus()
      ->mutable_media_controls_rpt_220()
      ->set_input_output_fault(input_output_fault(bytes, length));
  chassis->mutable_lexus()->mutable_media_controls_rpt_220()->set_enabled(
      enabled(bytes, length));
  chassis->mutable_lexus()
      ->mutable_media_controls_rpt_220()
      ->set_command_output_fault(command_output_fault(bytes, length));

  delete[] obj_lam;

  free(rind_g);
  free(cind_g);
  free(jacval);

  free(rind_L);
  free(cind_L);
  free(hessval);
}

void DistanceApproachIPOPTFixedDualInterface::get_optimization_results(
    Eigen::MatrixXd* state_result, Eigen::MatrixXd* control_result,
    Eigen::MatrixXd* time_result, Eigen::MatrixXd* dual_l_result,
    Eigen::MatrixXd* dual_n_result) const {
  ADEBUG << "get_optimization_results";
  *state_result = state_result_;
  *control_result = control_result_;
  *time_result = time_result_;
  *dual_l_result = dual_l_result_;
  *dual_n_result = dual_n_result_;

  if (!distance_approach_config_.enable_initial_final_check()) return;
  CHECK_EQ(state_result_.cols(), xWS_.cols());
  CHECK_EQ(state_result_.rows(), xWS_.rows());
  double state_diff_max = 0.0;
  for (int i = 0; i < horizon_ + 1; ++i) {
    for (int j = 0; j < 4; ++j) {
      state_diff_max =
          std::max(std::abs(xWS_(j, i) - state_result_(j, i)), state_diff_max);
    }
  }

  // 2. control variable initialization, 2 * horizon_
  CHECK_EQ(control_result_.cols(), uWS_.cols());

    AINFO << "This drive mode no need to set gear.";
    return;
  }

  switch (gear_position) {
    case Chassis::GEAR_NEUTRAL: {
      gear_control_a1_->set_gear_state_target(
          Gear_control_a1::GEAR_STATE_TARGET_N);
      break;
    }
    case Chassis::GEAR_REVERSE: {
      gear_control_a1_->set_gear_state_target(
          Gear_control_a1::GEAR_STATE_TARGET_R);
      break;
    }
    case Chassis::GEAR_DRIVE: {
      gear_control_a1_->set_gear_state_target(
          Gear_control_a1::GEAR_STATE_TARGET_D);
      break;
    }
    case Chassis::GEAR_PARKING: {
      gear_control_a1_->set_gear_state_target(
          Gear_control_a1::GEAR_STATE_TARGET_P);
      break;
    }

    case Chassis::GEAR_INVALID: {
      AERROR << "Gear command is invalid!";
      gear_control_a1_->set_gear_state_target(
          Gear_control_a1::GEAR_STATE_TARGET_INVALID);
      break;
    }
    default: {
      gear_control_a1_->set_gear_state_target(
          Gear_control_a1::GEAR_STATE_TARGET_P);
      break;
    }
  }
}

