// config detail: {'name': 'manual_input', 'offset': 0.0, 'precision': 0.001,
// 'len': 16, 'is_signed_var': False, 'physical_range': '[0|1]', 'bit': 7,
// 'type': 'double', 'order': 'motorola', 'physical_unit': '%'}
double Brakerpt6c::manual_input(const std::uint8_t* bytes,
                                int32_t length) const {
  Byte t0(bytes + 0);
  int32_t x = t0.get_byte(0, 8);

  Byte t1(bytes + 1);
  int32_t t = t1.get_byte(0, 8);
  x <<= 8;
  x |= t;

  double ret = x * 0.001000;
  return ret;
}

// config detail: {'name': 'commanded_value', 'offset': 0.0, 'precision': 0.001,
// 'len': 16, 'is_signed_var': False, 'physical_range': '[0|1]', 'bit': 23,
// 'type': 'double', 'order': 'motorola', 'physical_unit': '%'}
double Brakerpt6c::commanded_value(const std::uint8_t* bytes,
                                   int32_t length) const {
  Byte t0(bytes + 2);
  int32_t x = t0.get_byte(0, 8);

  Byte t1(bytes + 3);
  int32_t t = t1.get_byte(0, 8);
  x <<= 8;
  x |= t;

bool DistanceApproachIPOPTInterface::get_nlp_info(int& n, int& m,
                                                  int& nnz_jac_g,
                                                  int& nnz_h_lag,
                                                  IndexStyleEnum& index_style) {
  ADEBUG << "get_nlp_info";
  // n1 : states variables, 4 * (N+1)
  int n1 = 4 * (horizon_ + 1);
  ADEBUG << "n1: " << n1;
  // n2 : control inputs variables
  int n2 = 2 * horizon_;
  ADEBUG << "n2: " << n2;
  // n3 : sampling time variables
  int n3 = horizon_ + 1;
  ADEBUG << "n3: " << n3;
  // n4 : dual multiplier associated with obstacle shape
  lambda_horizon_ = obstacles_edges_num_.sum() * (horizon_ + 1);
  ADEBUG << "lambda_horizon_: " << lambda_horizon_;
  // n5 : dual multipier associated with car shape, obstacles_num*4 * (N+1)
  miu_horizon_ = obstacles_num_ * 4 * (horizon_ + 1);
  ADEBUG << "miu_horizon_: " << miu_horizon_;

  // m1 : dynamics constatins
  int m1 = 4 * horizon_;
  // m2 : control rate constraints (only steering)
  int m2 = horizon_;
  // m3 : sampling time equality constraints
  int m3 = horizon_;
  // m4 : obstacle constraints
  int m4 = 4 * obstacles_num_ * (horizon_ + 1);

  num_of_variables_ = n1 + n2 + n3 + lambda_horizon_ + miu_horizon_;
  num_of_constraints_ =
      m1 + m2 + m3 + m4 + (num_of_variables_ - (horizon_ + 1) + 2);

  // number of variables
  n = num_of_variables_;
  ADEBUG << "num_of_variables_ " << num_of_variables_;
  // number of constraints
  m = num_of_constraints_;
  ADEBUG << "num_of_constraints_ " << num_of_constraints_;

plane[2] = up[nm1].IsValid() ? up[nm1].params : nullptr;
plane[3] = dn[nm1].IsValid() ? dn[nm1].params : nullptr;
iter = (*vg_coarse_)(r, nm1).indices_.cbegin();
while (iter < (*vg_coarse_)(r, nm1).indices_.cend()) {
  pos = *iter;
  assert(pos < static_cast<int>(nr_points));
  label = labels_[pos];
  cptr = point_cloud + (nr_point_elements * pos);
  dist[0] = plane[0] != nullptr
                ? IPlaneToPointSignedDistanceWUnitNorm(plane[0], cptr)
                : FLT_MAX;
  min_abs_dist = IAbs(dist[0]);
  id = 0;
  // for candidates we take min dist:
  if (label) {
    dist[1] = plane[1] != nullptr
                  ? IPlaneToPointSignedDistanceWUnitNorm(plane[1], cptr)
                  : FLT_MAX;
    dist[2] = plane[2] != nullptr
                  ? IPlaneToPointSignedDistanceWUnitNorm(plane[2], cptr)
                  : FLT_MAX;
    dist[3] = plane[3] != nullptr
                  ? IPlaneToPointSignedDistanceWUnitNorm(plane[3], cptr)
                  : FLT_MAX;

  dst[4] = src[4];
  dst[5] = src[5];
  dst[6] = src[6];
  dst[7] = src[7];
  dst[8] = src[8];
  dst[9] = src[9];
  dst[10] = src[10];
  dst[11] = src[11];
  dst[12] = src[12];
  dst[13] = src[13];
}
template <typename T>
inline void ICopy15(const T src[15], T dst[15]) {
  dst[0] = src[0];
  dst[1] = src[1];
  dst[2] = src[2];
  dst[3] = src[3];
  dst[4] = src[4];
  dst[5] = src[5];
  dst[6] = src[6];
  dst[7] = src[7];
  dst[8] = src[8];
  dst[9] = src[9];
  dst[10] = src[10];

road_boundary_ptr->id = road_ptr->id();
for (const auto& temp_road_boundary : temp_roads_roi) {
  apollo::hdmap::BoundaryPolygon boundary_polygon =
      temp_road_boundary.outer_polygon();
  for (const auto& edge : boundary_polygon.edge()) {
    if (edge.type() == apollo::hdmap::BoundaryEdge::LEFT_BOUNDARY) {
      for (const auto& s : edge.curve().segment()) {
        for (const auto& p : s.line_segment().point()) {
          road_boundary_ptr->left_boundary.line_points.push_back(p);
        }
      }
    }
    if (edge.type() == apollo::hdmap::BoundaryEdge::RIGHT_BOUNDARY) {
      for (const auto& s : edge.curve().segment()) {
        for (const auto& p : s.line_segment().point()) {
          road_boundary_ptr->right_boundary.line_points.push_back(p);
        }
      }
    }
  }
  if (temp_road_boundary.hole_size() != 0) {
    for (const auto& hole : temp_road_boundary.hole()) {
      PolygonBoundary hole_boundary;
      for (const auto& edge : hole.edge()) {
        if (edge.type() == apollo::hdmap::BoundaryEdge::NORMAL) {
          for (const auto& s : edge.curve().segment()) {
            for (const auto& p : s.line_segment().point()) {
              hole_boundary.polygon_points.push_back(p);
            }
          }
        }
      }
      road_boundary_ptr->holes_boundary.push_back(hole_boundary);
    }
  }
}
roads_roi->push_back(road_boundary_ptr);

template <typename T>
inline void IMultAB3x3And3x3(const T A[9], const T B[9], T AB[9]) {
  T a, b, c;
  a = A[0];
  b = A[1];
  c = A[2];
  AB[0] = a * B[0] + b * B[3] + c * B[6];
  AB[1] = a * B[1] + b * B[4] + c * B[7];
  AB[2] = a * B[2] + b * B[5] + c * B[8];
  a = A[3];
  b = A[4];
  c = A[5];
  AB[3] = a * B[0] + b * B[3] + c * B[6];
  AB[4] = a * B[1] + b * B[4] + c * B[7];
  AB[5] = a * B[2] + b * B[5] + c * B[8];
  a = A[6];
  b = A[7];
  c = A[8];
  AB[6] = a * B[0] + b * B[3] + c * B[6];
  AB[7] = a * B[1] + b * B[4] + c * B[7];
  AB[8] = a * B[2] + b * B[5] + c * B[8];
}

