bool LincolnController::Start() {
  if (!is_initialized_) {
    AERROR << "LincolnController has NOT been initiated.";
    return false;
  }
  const auto &update_func = [this] { SecurityDogThreadFunc(); };
  thread_.reset(new std::thread(update_func));

  return true;
}

void LincolnController::Stop() {
  if (!is_initialized_) {
    AERROR << "LincolnController stops or starts improperly!";
    return;
  }

  if (thread_ != nullptr && thread_->joinable()) {
    thread_->join();
    thread_.reset();
    AINFO << "LincolnController stopped.";
  }
}

Chassis LincolnController::chassis() {
  chassis_.Clear();

  ChassisDetail chassis_detail;
  message_manager_->GetSensorData(&chassis_detail);

  // 21, 22, previously 1, 2
  if (driving_mode() == Chassis::EMERGENCY_MODE) {
    set_chassis_error_code(Chassis::NO_ERROR);
  }

  chassis_.set_driving_mode(driving_mode());
  chassis_.set_error_code(chassis_error_code());

  // 3
  chassis_.set_engine_started(true);

chassis_.set_fuel_range_m(0);
// 8
if (wey.has_fbs3_237() && wey.fbs3_237().has_accpedalpos()) {
  chassis_.set_throttle_percentage(
      static_cast<float>(wey.fbs3_237().accpedalpos()));
} else {
  chassis_.set_throttle_percentage(0);
}
// 23, previously 10 gear position
if (wey.has_fbs3_237() && wey.fbs3_237().has_currentgear()) {
  switch (wey.fbs3_237().currentgear()) {
    case Fbs3_237::CURRENTGEAR_D: {
      chassis_.set_gear_location(Chassis::GEAR_DRIVE);
    } break;
    case Fbs3_237::CURRENTGEAR_N: {
      chassis_.set_gear_location(Chassis::GEAR_NEUTRAL);
    } break;
    case Fbs3_237::CURRENTGEAR_R: {
      chassis_.set_gear_location(Chassis::GEAR_REVERSE);
    } break;
    case Fbs3_237::CURRENTGEAR_P: {
      chassis_.set_gear_location(Chassis::GEAR_PARKING);
    } break;
    default:
      chassis_.set_gear_location(Chassis::GEAR_INVALID);
      break;
  }
} else {
  chassis_.set_gear_location(Chassis::GEAR_NONE);

  AddSendProtocolData<Turncmd63, true>();
  AddSendProtocolData<Wipercmd90, true>();

  // Report Messages
  AddRecvProtocolData<Accelrpt68, true>();
  AddRecvProtocolData<Brakemotorrpt170, true>();
  AddRecvProtocolData<Brakemotorrpt271, true>();
  AddRecvProtocolData<Brakemotorrpt372, true>();
  AddRecvProtocolData<Brakerpt6c, true>();
  AddRecvProtocolData<Datetimerpt83, true>();
  AddRecvProtocolData<Globalrpt6a, true>();
  AddRecvProtocolData<Headlightrpt77, true>();
  AddRecvProtocolData<Hornrpt79, true>();
  AddRecvProtocolData<Latlonheadingrpt82, true>();
  AddRecvProtocolData<Parkingbrakestatusrpt80, true>();
  AddRecvProtocolData<Shiftrpt66, true>();
  AddRecvProtocolData<Steeringmotorrpt173, true>();
  AddRecvProtocolData<Steeringmotorrpt274, true>();
  AddRecvProtocolData<Steeringmotorrpt375, true>();
  AddRecvProtocolData<Steeringrpt16e, true>();
  AddRecvProtocolData<Turnrpt64, true>();
  AddRecvProtocolData<Vehiclespeedrpt6f, true>();
  AddRecvProtocolData<Wheelspeedrpt7a, true>();
  AddRecvProtocolData<Wiperrpt91, true>();
  AddRecvProtocolData<Yawraterpt81, true>();
}

