// 'physical_unit': 'rad/s'}
int Wheelspeedrpt7a::wheel_spd_rear_right(const std::uint8_t* bytes,
                                          int32_t length) const {
  Byte t0(bytes + 6);
  int32_t x = t0.get_byte(0, 8);

  Byte t1(bytes + 7);
  int32_t t = t1.get_byte(0, 8);
  x <<= 8;
  x |= t;

  x <<= 16;
  x >>= 16;

  int ret = x;
  return ret;
}

