Status LanesXmlParser::ParseObjectOverlapGroup(
    const tinyxml2::XMLElement& xml_node,
    std::vector<OverlapWithLane>* object_overlaps) {
  CHECK_NOTNULL(object_overlaps);

  auto object_overlap = xml_node.FirstChildElement("objectOverlapGroup");
  if (object_overlap) {
    auto sub_node = object_overlap->FirstChildElement("objectReference");
    while (sub_node) {
      std::string object_id;
      double start_s = 0.0;
      double end_s = 0.0;
      int checker =
          UtilXmlParser::QueryStringAttribute(*sub_node, "id", &object_id);
      checker += sub_node->QueryDoubleAttribute("startOffset", &start_s);
      checker += sub_node->QueryDoubleAttribute("endOffset", &end_s);
      if (checker != tinyxml2::XML_SUCCESS) {
        std::string err_msg = "Error parse lane object overlap";
        return Status(apollo::common::ErrorCode::HDMAP_DATA_ERROR, err_msg);
      }

      bool is_merge = false;
      checker = sub_node->QueryBoolAttribute("isMerge", &is_merge);
      if (checker != tinyxml2::XML_SUCCESS) {
        is_merge = false;
      }

      OverlapWithLane overlap_with_lane;
      overlap_with_lane.object_id = object_id;
      overlap_with_lane.start_s = start_s;
      overlap_with_lane.end_s = end_s;
      overlap_with_lane.is_merge = is_merge;

RSPParam LRL5_param;
LRL(xb, yb, phi, &LRL5_param);
double LRL5_lengths[3] = {LRL5_param.v, LRL5_param.u, LRL5_param.t};
char LRL5_types[] = "LRL";
if (LRL5_param.flag &&
    !SetRSP(3, LRL5_lengths, LRL5_types, all_possible_paths)) {
  ADEBUG << "Fail at SetRSP with LRL5_param";
  return false;
}

RSPParam LRL6_param;
LRL(-xb, yb, -phi, &LRL6_param);
double LRL6_lengths[3] = {-LRL6_param.v, -LRL6_param.u, -LRL6_param.t};
char LRL6_types[] = "LRL";
if (LRL6_param.flag &&
    !SetRSP(3, LRL6_lengths, LRL6_types, all_possible_paths)) {
  ADEBUG << "Fail at SetRSP with LRL6_param";
  return false;
}

RSPParam LRL7_param;
LRL(xb, -yb, -phi, &LRL7_param);
double LRL7_lengths[3] = {LRL7_param.v, LRL7_param.u, LRL7_param.t};
char LRL7_types[] = "RLR";
if (LRL7_param.flag &&
    !SetRSP(3, LRL7_lengths, LRL7_types, all_possible_paths)) {
  ADEBUG << "Fail at SetRSP with LRL7_param";
  return false;
}

RSPParam LRL8_param;
LRL(-xb, -yb, phi, &LRL8_param);
double LRL8_lengths[3] = {-LRL8_param.v, -LRL8_param.u, -LRL8_param.t};
char LRL8_types[] = "RLR";
if (LRL8_param.flag &&
    !SetRSP(3, LRL8_lengths, LRL8_types, all_possible_paths)) {
  ADEBUG << "Fail at SetRSP with LRL8_param";
  return false;
}
return true;

