inline int IMaxAbsIndexInterval(const double *a, int i1, int i2) {
  int bi;
  double b, t;
  b = IAbs(a[i1]);
  bi = i1;
  for (int i = i1 + 1; i < i2; i++) {
    if ((t = IAbs(a[i])) > b) {
      b = t;
      bi = i;
    }
  }
  return (bi);
