// 'bit': 15, 'type': 'double', 'order': 'motorola', 'physical_unit': 'rad'}
double Steeringrpt22c::manual_input(const std::uint8_t* bytes,
                                    int32_t length) const {
  Byte t0(bytes + 1);
  int32_t x = t0.get_byte(0, 8);

  Byte t1(bytes + 2);
