bool OpenSpaceROI() {
  // left or right of the parking lot is decided when viewing the parking spot
  // open upward
  Vec2d left_top = target_parking_spot_->polygon().points().at(3);
  Vec2d left_down = target_parking_spot_->polygon().points().at(0);
  Vec2d right_top = target_parking_spot_->polygon().points().at(2);
  Vec2d right_down = target_parking_spot_->polygon().points().at(1);
  double left_top_s = 0.0;
  double left_top_l = 0.0;
  double right_top_s = 0.0;
  double right_top_l = 0.0;
  if (!(nearby_path_->GetProjection(left_top, &left_top_s, &left_top_l) &&
        nearby_path_->GetProjection(right_top, &right_top_s, &right_top_l))) {
    std::string msg(
        "fail to get parking spot points' projections on reference line");
    AERROR << msg;
    return false;
  }
  // start or end, left or right is decided by the vehicle's heading
  double center_line_s = (left_top_s + right_top_s) / 2;
  double start_s =
      center_line_s -
      planner_open_space_config_.roi_config().roi_longitudinal_range();
  double end_s =
      center_line_s +
      planner_open_space_config_.roi_config().roi_longitudinal_range();
  hdmap::MapPathPoint end_point = nearby_path_->GetSmoothPoint(end_s);
  hdmap::MapPathPoint start_point = nearby_path_->GetSmoothPoint(start_s);
  double start_left_width = nearby_path_->GetRoadLeftWidth(start_s);
  double start_right_width = nearby_path_->GetRoadRightWidth(start_s);
  double end_left_width = nearby_path_->GetRoadLeftWidth(end_s);
  double end_right_width = nearby_path_->GetRoadRightWidth(end_s);
  double start_right_vec_cos = std::cos(start_point.heading() - M_PI / 2);
  double start_right_vec_sin = std::sin(start_point.heading() - M_PI / 2);
  double start_left_vec_cos = std::cos(start_point.heading() + M_PI / 2);
  double start_left_vec_sin = std::sin(start_point.heading() + M_PI / 2);
  double end_right_vec_cos = std::cos(end_point.heading() - M_PI / 2);
  double end_right_vec_sin = std::sin(end_point.heading() - M_PI / 2);
  double end_left_vec_cos = std::cos(end_point.heading() + M_PI / 2);
  double end_left_vec_sin = std::sin(end_point.heading() + M_PI / 2);

  Vec2d start_right = Vec2d(start_right_width * start_right_vec_cos,
                            start_right_width * start_right_vec_sin);
  start_right = start_right + start_point;
  Vec2d start_left = Vec2d(start_left_width * start_left_vec_cos,
                           start_left_width * start_left_vec_sin);
  start_left = start_left + start_point;
  Vec2d end_right = Vec2d(end_right_width * end_right_vec_cos,
                          end_right_width * end_right_vec_sin);
  end_right = end_right + end_point;
  Vec2d end_left = Vec2d(end_left_width * end_left_vec_cos,
                         end_left_width * end_left_vec_sin);
  end_left = end_left + end_point;

    for (int i = 0; i < lambda_horizon_; ++i) {
      values[nz_index] = 1.0;
      ++nz_index;
    }
    for (int i = 0; i < miu_horizon_; ++i) {
      values[nz_index] = 1.0;
      ++nz_index;
    }

    ADEBUG << "eval_jac_g, fulfilled obstacle constraint values";
    CHECK_EQ(nz_index, nele_jac);
  }

  ADEBUG << "eval_jac_g done";
  return true;
}

bool DualVariableWarmStartIPOPTQPInterface::eval_h(
    int n, const double* x, bool new_x, double obj_factor, int m,
    const double* lambda, bool new_lambda, int nele_hess, int* iRow, int* jCol,
    double* values) {
  if (values == nullptr) {
    // return the structure. This is a symmetric matrix, fill the lower left
    // triangle only.
    for (int idx = 0; idx < nnz_L; idx++) {
      iRow[idx] = rind_L[idx];
      jCol[idx] = cind_L[idx];
    }
  } else {
    // return the values. This is a symmetric matrix, fill the lower left
    // triangle only
    obj_lam[0] = obj_factor;
    for (int idx = 0; idx < m; idx++) obj_lam[1 + idx] = lambda[idx];

    set_param_vec(tag_L, m + 1, obj_lam);
    sparse_hess(tag_L, n, 1, const_cast<double*>(x), &nnz_L, &rind_L, &cind_L,
                &hessval, options_L);

    for (int idx = 0; idx < nnz_L; idx++) {
      values[idx] = hessval[idx];
    }
  }

  return true;
}

void DualVariableWarmStartIPOPTQPInterface::finalize_solution(
    Ipopt::SolverReturn status, int n, const double* x, const double* z_L,
    const double* z_U, int m, const double* g, const double* lambda,
    double obj_value, const Ipopt::IpoptData* ip_data,
    Ipopt::IpoptCalculatedQuantities* ip_cq) {
  int variable_index = 0;
  // 1. lagrange constraint l, [0, obstacles_edges_sum_ - 1] * [0,
  // horizon_]
  for (int i = 0; i < horizon_ + 1; ++i) {
    for (int j = 0; j < obstacles_edges_sum_; ++j) {
      l_warm_up_(j, i) = x[variable_index];
      ++variable_index;
    }
  }
  ADEBUG << "variable_index after adding lagrange l : " << variable_index;

  // 2. lagrange constraint n, [0, 4*obstacles_num-1] * [0, horizon_]
  for (int i = 0; i < horizon_ + 1; ++i) {
    for (int j = 0; j < 4 * obstacles_num_; ++j) {
      n_warm_up_(j, i) = x[variable_index];
      ++variable_index;
    }
  }
  ADEBUG << "variable_index after adding lagrange n : " << variable_index;

  // memory deallocation of ADOL-C variables
  delete[] obj_lam;
  free(rind_L);
  free(cind_L);
  free(hessval);
}

void DualVariableWarmStartIPOPTQPInterface::get_optimization_results(
    Eigen::MatrixXd* l_warm_up, Eigen::MatrixXd* n_warm_up) const {
  *l_warm_up = l_warm_up_;
  *n_warm_up = n_warm_up_;

  boo_cmd_ = false;
  return this;
}

Brake60 *Brake60::set_enable() {
  pedal_enable_ = true;
  return this;
}

Brake60 *Brake60::set_disable() {
  pedal_enable_ = false;
  return this;
}

void Brake60::set_pedal_p(uint8_t *data, double pedal) {
  // change from [0-100] to [0.00-1.00]
  // and a rough mapping
  pedal /= 100.;
  pedal = ProtocolData::BoundedValue(0.0, 1.0, pedal);
  int32_t x = static_cast<int32_t>(pedal / 1.52590218966964e-05);
  std::uint8_t t = 0;

  t = static_cast<uint8_t>(x & 0xFF);
  Byte frame_low(data + 0);
  frame_low.set_value(t, 0, 8);

  x >>= 8;
  t = static_cast<uint8_t>(x & 0xFF);
  Byte frame_high(data + 1);
  frame_high.set_value(t, 0, 8);
}

void Brake60::set_boo_cmd_p(uint8_t *bytes, bool boo_cmd) {
  Byte frame(bytes + 2);
  if (boo_cmd) {
    frame.set_bit_1(0);
  } else {
    frame.set_bit_0(0);
  }
}

void Brake60::set_enable_p(uint8_t *bytes, bool enable) {
  Byte frame(bytes + 3);
  if (enable) {
    frame.set_bit_1(0);
  } else {
    frame.set_bit_0(0);
  }
}

void Brake60::set_clear_driver_override_flag_p(uint8_t *bytes, bool clear) {
  Byte frame(bytes + 3);
  if (clear) {
    frame.set_bit_1(1);
  } else {
    frame.set_bit_0(1);
  }
}

void Brake60::set_watchdog_counter_p(uint8_t *data, int32_t count) {
  count = ProtocolData::BoundedValue(0, 255, count);
  Byte frame(data + 7);
  frame.set_value(static_cast<uint8_t>(count), 0, 8);

