std::vector<adouble> xa(n);
std::vector<adouble> g(m);
std::vector<double> lam(m);

double sig;
adouble obj_value;
double dummy = 0.0;
obj_lam = new double[m + 1];
get_starting_point(n, 1, &xp[0], 0, &zl[0], &zu[0], m, 0, &lamp[0]);

trace_on(tag_f);
for (int idx = 0; idx < n; idx++) {
  xa[idx] <<= xp[idx];
}
eval_obj(n, &xa[0], &obj_value);
obj_value >>= dummy;
trace_off();

trace_on(tag_g);
for (int idx = 0; idx < n; idx++) {
  xa[idx] <<= xp[idx];
}
eval_constraints(n, &xa[0], m, &g[0]);
for (int idx = 0; idx < m; idx++) {
  g[idx] >>= dummy;
}
trace_off();

trace_on(tag_L);
for (int idx = 0; idx < n; idx++) {
  xa[idx] <<= xp[idx];
}
for (int idx = 0; idx < m; idx++) {
  lam[idx] = 1.0;
}
sig = 1.0;
eval_obj(n, &xa[0], &obj_value);
obj_value *= mkparam(sig);
eval_constraints(n, &xa[0], m, &g[0]);
for (int idx = 0; idx < m; idx++) {
  obj_value += g[idx] * mkparam(lam[idx]);
}
obj_value >>= dummy;

trace_off();

rind_g = nullptr;
cind_g = nullptr;
jacval = nullptr;
