void ObstacleCameraPerception::InitCalibrationService(
    const std::string &work_root, const base::BaseCameraModelPtr model,
    const app::PerceptionParam &perception_param) {
  // Init calibration service
  CHECK(perception_param.has_calibration_service_param())
      << "Failed to include calibration_service_param.";
  {
    auto calibration_service_param =
        perception_param.calibration_service_param();
    CalibrationServiceInitOptions calibration_service_init_options;
    calibration_service_init_options.calibrator_working_sensor_name =
        lane_calibration_working_sensor_name_;
    calibration_service_init_options.name_intrinsic_map = name_intrinsic_map_;
    calibration_service_init_options.calibrator_method =
        calibration_service_param.calibrator_method();
    calibration_service_init_options.image_height =
        static_cast<int>(model->get_height());
    calibration_service_init_options.image_width =
        static_cast<int>(model->get_width());
    calibration_service_.reset(
        BaseCalibrationServiceRegisterer::GetInstanceByName(
            calibration_service_param.plugin_param().name()));
    CHECK(calibration_service_ != nullptr);
    CHECK(calibration_service_->Init(calibration_service_init_options))

if (obstacles_num != obstacles_vertices_vec.size()) {
  AERROR << "obstacles_num != obstacles_vertices_vec.size()";
  return false;
}

A_all->resize(obstacles_edges_num.sum(), 2);
b_all->resize(obstacles_edges_num.sum(), 1);

int counter = 0;
double kEpsilon = 1.0e-5;
// start building H representation
for (size_t i = 0; i < obstacles_num; ++i) {
  size_t current_vertice_num = obstacles_edges_num(i, 0);
  Eigen::MatrixXd A_i(current_vertice_num, 2);
  Eigen::MatrixXd b_i(current_vertice_num, 1);

  // take two subsequent vertices, and computer hyperplane
  for (size_t j = 0; j < current_vertice_num; ++j) {
    Vec2d v1 = obstacles_vertices_vec[i][j];
    Vec2d v2 = obstacles_vertices_vec[i][j + 1];

    Eigen::MatrixXd A_tmp(2, 1), b_tmp(1, 1), ab(2, 1);
    // find hyperplane passing through v1 and v2
    if (std::abs(v1.x() - v2.x()) < kEpsilon) {
      if (v2.y() < v1.y()) {
        A_tmp << 1, 0;
        b_tmp << v1.x();
      } else {
        A_tmp << -1, 0;
        b_tmp << -v1.x();
      }
    } else if (std::abs(v1.y() - v2.y()) < kEpsilon) {
      if (v1.x() < v2.x()) {
        A_tmp << 0, 1;
        b_tmp << v1.y();
      } else {
        A_tmp << 0, -1;
        b_tmp << -v1.y();
      }
    } else {
      Eigen::MatrixXd tmp1(2, 2);
      tmp1 << v1.x(), 1, v2.x(), 1;
      Eigen::MatrixXd tmp2(2, 1);
      tmp2 << v1.y(), v2.y();
      ab = tmp1.inverse() * tmp2;
      double a = ab(0, 0);
      double b = ab(1, 0);

      if (v1.x() < v2.x()) {
        A_tmp << -a, 1;
        b_tmp << b;
      } else {
        A_tmp << a, -1;
        b_tmp << -b;
      }
    }

    // store vertices
    A_i.block(j, 0, 1, 2) = A_tmp.transpose();
    b_i.block(j, 0, 1, 1) = b_tmp;
  }

  A_all->block(counter, 0, A_i.rows(), 2) = A_i;
  b_all->block(counter, 0, b_i.rows(), 1) = b_i;
  counter += static_cast<int>(current_vertice_num);
}
return true;

  return lane_ids;
}

bool PredictionMap::IsLeftNeighborLane(
    std::shared_ptr<const LaneInfo> target_lane,
    std::shared_ptr<const LaneInfo> curr_lane) {
  if (curr_lane == nullptr) {
    return true;
  }
  if (target_lane == nullptr) {
    return false;
  }
  for (const auto& left_lane_id :
       curr_lane->lane().left_neighbor_forward_lane_id()) {
    if (target_lane->id().id() == left_lane_id.id()) {
      return true;
    }
  }
  return false;
}

bool PredictionMap::IsLeftNeighborLane(
    std::shared_ptr<const LaneInfo> target_lane,
    const std::vector<std::shared_ptr<const LaneInfo>>& lanes) {
  if (lanes.empty()) {
    return true;
  }
  for (auto& lane : lanes) {
    if (IsLeftNeighborLane(target_lane, lane)) {
      return true;
    }
  }
  return false;
}

