void GnssMagTransfer::Transfer(const apollo::drivers::gnss::GlonassOrbit& in,
                               GlonassOrbitMsg* out) {
  CHECK_NOTNULL(out);
  if (in.has_gnss_type()) {
    out->set_gnss_type(GnssType(in.gnss_type()));
  }
  if (in.has_slot_prn()) {
    out->set_slot_prn(in.slot_prn());
  }
  if (in.has_gnss_time_type()) {
    out->set_gnss_time_type(GnssTimeType(in.gnss_time_type()));
  }
  if (in.has_toe()) {
    out->set_toe(in.toe());
  }
  if (in.has_year()) {
    out->set_year(in.year());
  }
  if (in.has_month()) {
    out->set_month(in.month());
  }
  if (in.has_day()) {
    out->set_day(in.day());
  }
  if (in.has_hour()) {
    out->set_hour(in.hour());
  }
  if (in.has_minute()) {
    out->set_minute(in.minute());
  }
  if (in.has_second_s()) {
    out->set_second_s(in.second_s());
  }
  if (in.has_frequency_no()) {
    out->set_frequency_no(in.frequency_no());
  }
  if (in.has_week_num()) {
    out->set_week_num(in.week_num());
  }
  if (in.has_week_second_s()) {
    out->set_week_second_s(in.week_second_s());
  }
  if (in.has_tk()) {
    out->set_tk(in.tk());
  }
  if (in.has_clock_offset()) {
    out->set_clock_offset(in.clock_offset());
  }
  if (in.has_clock_drift()) {
    out->set_clock_drift(in.clock_drift());
  }
  if (in.has_health()) {
    out->set_health(in.health());
  }
  if (in.has_position_x()) {
    out->set_position_x(in.position_x());
  }
  if (in.has_position_y()) {
    out->set_position_y(in.position_y());
  }
  if (in.has_position_z()) {
    out->set_position_z(in.position_z());
  }
  if (in.has_velocity_x()) {
    out->set_velocity_x(in.velocity_x());
  }
  if (in.has_velocity_y()) {
    out->set_velocity_y(in.velocity_y());
  }
  if (in.has_velocity_z()) {
    out->set_velocity_z(in.velocity_z());
  }
  if (in.has_accelerate_x()) {
    out->set_accelerate_x(in.accelerate_x());
  }
  if (in.has_accelerate_y()) {
    out->set_accelerate_y(in.accelerate_y());
  }
  if (in.has_accelerate_z()) {
    out->set_accelerate_z(in.accelerate_z());
  }
  if (in.has_infor_age()) {
    out->set_infor_age(in.infor_age());

  return true;
}

/** Method to generate the required tapes */
void FemPosDeviationIpoptInterface::generate_tapes(int n, int m, int* nnz_jac_g,
                                                   int* nnz_h_lag) {
  std::vector<double> xp(n, 0.0);
  std::vector<double> lamp(m, 0.0);
  std::vector<double> zl(m, 0.0);
  std::vector<double> zu(m, 0.0);
  std::vector<adouble> xa(n, 0.0);
  std::vector<adouble> g(m, 0.0);
  std::vector<double> lam(m, 0.0);

  double sig;
  adouble obj_value;

  double dummy = 0.0;
  obj_lam_.clear();
  obj_lam_.resize(m + 1, 0.0);
  get_starting_point(n, 1, &xp[0], 0, &zl[0], &zu[0], m, 0, &lamp[0]);

  // Trace on Objectives
  trace_on(tag_f);
  for (int idx = 0; idx < n; idx++) {
    xa[idx] <<= xp[idx];
  }
  eval_obj(n, &xa[0], &obj_value);
  obj_value >>= dummy;
  trace_off();

  // Trace on Jacobian
  trace_on(tag_g);
  for (int idx = 0; idx < n; idx++) {
    xa[idx] <<= xp[idx];
  }
  eval_constraints(n, &xa[0], m, &g[0]);
  for (int idx = 0; idx < m; idx++) {
    g[idx] >>= dummy;
  }
  trace_off();

  // Trace on Hessian
  trace_on(tag_L);
  for (int idx = 0; idx < n; idx++) {
    xa[idx] <<= xp[idx];
  }
  for (int idx = 0; idx < m; idx++) {
    lam[idx] = 1.0;
  }
  sig = 1.0;
  eval_obj(n, &xa[0], &obj_value);
  obj_value *= mkparam(sig);
  eval_constraints(n, &xa[0], m, &g[0]);
  for (int idx = 0; idx < m; idx++) {
    obj_value += g[idx] * mkparam(lam[idx]);
  }
  obj_value >>= dummy;
  trace_off();

  rind_g_ = nullptr;
  cind_g_ = nullptr;
  rind_L_ = nullptr;
  cind_L_ = nullptr;

  options_g_[0] = 0; /* sparsity pattern by index domains (default) */
  options_g_[1] = 0; /*                         safe mode (default) */
  options_g_[2] = 0;
  options_g_[3] = 0; /*                column compression (default) */

  jacval_ = nullptr;
  hessval_ = nullptr;

  sparse_jac(tag_g, m, n, 0, &xp[0], &nnz_jac_, &rind_g_, &cind_g_, &jacval_,
             options_g_);
  *nnz_jac_g = nnz_jac_;
  options_L_[0] = 0;
  options_L_[1] = 1;
  sparse_hess(tag_L, n, 0, &xp[0], &nnz_L_, &rind_L_, &cind_L_, &hessval_,
              options_L_);
  *nnz_h_lag = nnz_L_;

  return ret;
}

