ErrorCode WeyController::Init(
    const VehicleParameter& params,
    CanSender<::apollo::canbus::ChassisDetail>* const can_sender,
    MessageManager<::apollo::canbus::ChassisDetail>* const message_manager) {
  if (is_initialized_) {
    AINFO << "WeyController has already been initialized.";
    return ErrorCode::CANBUS_ERROR;
  }
  vehicle_params_.CopyFrom(
      common::VehicleConfigHelper::Instance()->GetConfig().vehicle_param());
  params_.CopyFrom(params);
  if (!params_.has_driving_mode()) {
    AERROR << "Vehicle conf pb not set driving_mode.";
    return ErrorCode::CANBUS_ERROR;
  }

  if (can_sender == nullptr) {
    return ErrorCode::CANBUS_ERROR;
  }
  can_sender_ = can_sender;

  if (message_manager == nullptr) {
    AERROR << "Protocol manager is null.";
    return ErrorCode::CANBUS_ERROR;
  }
  message_manager_ = message_manager;

  // sender part
  ads1_111_ = dynamic_cast<Ads1111*>(
      message_manager_->GetMutableProtocolDataById(Ads1111::ID));
  if (ads1_111_ == nullptr) {
    AERROR << "Ads1111 does not exist in the WeyMessageManager!";
    return ErrorCode::CANBUS_ERROR;
  }

  ads3_38e_ = dynamic_cast<Ads338e*>(
      message_manager_->GetMutableProtocolDataById(Ads338e::ID));
  if (ads3_38e_ == nullptr) {
    AERROR << "Ads338e does not exist in the WeyMessageManager!";
    return ErrorCode::CANBUS_ERROR;
  }

  ads_eps_113_ = dynamic_cast<Adseps113*>(
      message_manager_->GetMutableProtocolDataById(Adseps113::ID));
  if (ads_eps_113_ == nullptr) {
    AERROR << "Adseps113 does not exist in the WeyMessageManager!";
    return ErrorCode::CANBUS_ERROR;
  }

  ads_req_vin_390_ = dynamic_cast<Adsreqvin390*>(
      message_manager_->GetMutableProtocolDataById(Adsreqvin390::ID));
  if (ads_req_vin_390_ == nullptr) {
    AERROR << "Adsreqvin390 does not exist in the WeyMessageManager!";
    return ErrorCode::CANBUS_ERROR;
  }

  ads_shifter_115_ = dynamic_cast<Adsshifter115*>(
      message_manager_->GetMutableProtocolDataById(Adsshifter115::ID));
  if (ads_shifter_115_ == nullptr) {
    AERROR << "Adsshifter115 does not exist in the WeyMessageManager!";
    return ErrorCode::CANBUS_ERROR;
  }

  can_sender_->AddMessage(Ads1111::ID, ads1_111_, false);
  can_sender_->AddMessage(Ads338e::ID, ads3_38e_, false);
  can_sender_->AddMessage(Adseps113::ID, ads_eps_113_, false);
  can_sender_->AddMessage(Adsreqvin390::ID, ads_req_vin_390_, false);
  can_sender_->AddMessage(Adsshifter115::ID, ads_shifter_115_, false);

  // Need to sleep to ensure all messages received
  AINFO << "WeyController is initialized.";

  is_initialized_ = true;
  return ErrorCode::OK;
}

WeyController::~WeyController() {}

bool WeyController::Start() {
  if (!is_initialized_) {
    AERROR << "WeyController has NOT been initialized.";
    return false;
  }
  const auto& update_func = [this] { SecurityDogThreadFunc(); };
  thread_.reset(new std::thread(update_func));

  return true;
}

void WeyController::Stop() {
  if (!is_initialized_) {
    AERROR << "WeyController stops or starts improperly!";
    return;
  }

  if (thread_ != nullptr && thread_->joinable()) {
    thread_->join();
    thread_.reset();
    AINFO << "WeyController stopped.";
  }
}

Chassis WeyController::chassis() {
  chassis_.Clear();

  ChassisDetail chassis_detail;
  message_manager_->GetSensorData(&chassis_detail);

  // 21, 22, previously 1, 2
  if (driving_mode() == Chassis::EMERGENCY_MODE) {
    set_chassis_error_code(Chassis::NO_ERROR);
  }

  chassis_.set_driving_mode(driving_mode());
  chassis_.set_error_code(chassis_error_code());

  // 3
  chassis_.set_engine_started(true);
  // if there is not wey, no chassis detail can be retrieved and return
  if (!chassis_detail.has_wey()) {
    AERROR << "NO WEY chassis information!";
    return chassis_;
  }
  Wey wey = chassis_detail.wey();

  // 4 engine_rpm
  if (wey.has_fbs3_237() && wey.fbs3_237().has_engspd()) {
    chassis_.set_engine_rpm(static_cast<float>(wey.fbs3_237().engspd()));
  } else {
    chassis_.set_engine_rpm(0);

ObjectQualityInfo60C::ObjectQualityInfo60C() {}
const uint32_t ObjectQualityInfo60C::ID = 0x60C;

void ObjectQualityInfo60C::Parse(const std::uint8_t* bytes, int32_t length,
                                 RacobitRadar* racobit_radar) const {
  int obj_id = object_id(bytes, length);

  for (int i = 0; i < racobit_radar->contiobs_size(); ++i) {
    if (racobit_radar->contiobs(i).obstacle_id() == obj_id) {
      auto obs = racobit_radar->mutable_contiobs(i);
      obs->set_longitude_dist_rms(
          LINEAR_RMS[longitude_dist_rms(bytes, length)]);
      obs->set_lateral_dist_rms(LINEAR_RMS[lateral_dist_rms(bytes, length)]);
      obs->set_longitude_vel_rms(LINEAR_RMS[longitude_vel_rms(bytes, length)]);
      obs->set_lateral_vel_rms(LINEAR_RMS[lateral_vel_rms(bytes, length)]);
      obs->set_longitude_accel_rms(
          LINEAR_RMS[longitude_accel_rms(bytes, length)]);
      obs->set_lateral_accel_rms(LINEAR_RMS[lateral_accel_rms(bytes, length)]);
      obs->set_oritation_angle_rms(
          ANGLE_RMS[oritation_angle_rms(bytes, length)]);
      obs->set_probexist(PROBOFEXIST[probexist(bytes, length)]);
      obs->set_meas_state(meas_state(bytes, length));
      break;
    }
  }
}

int ObjectQualityInfo60C::object_id(const std::uint8_t* bytes,
                                    int32_t length) const {
  Byte t0(bytes);
  int32_t x = t0.get_byte(0, 8);

  int ret = x;
  return ret;
}

int ObjectQualityInfo60C::longitude_dist_rms(const std::uint8_t* bytes,
                                             int32_t length) const {
  Byte t0(bytes + 1);
  int32_t x = t0.get_byte(3, 5);

  int ret = x;
  return ret;
}

int ObjectQualityInfo60C::lateral_dist_rms(const std::uint8_t* bytes,
                                           int32_t length) const {
  Byte t0(bytes + 1);
  int32_t x = t0.get_byte(0, 3);

  Byte t1(bytes + 2);
  int32_t t = t1.get_byte(6, 2);

  x <<= 2;
  x |= t;

  int ret = x;
  return ret;
}

int ObjectQualityInfo60C::longitude_vel_rms(const std::uint8_t* bytes,
                                            int32_t length) const {
  Byte t0(bytes + 2);
  int32_t x = t0.get_byte(1, 5);

  int ret = x;
  return ret;
}

int ObjectQualityInfo60C::lateral_vel_rms(const std::uint8_t* bytes,
                                          int32_t length) const {
  Byte t0(bytes + 2);
  int32_t x = t0.get_byte(0, 1);

  Byte t1(bytes + 3);
  int32_t t = t1.get_byte(4, 4);

  x <<= 4;
  x |= t;

  int ret = x;
  return ret;
}

int ObjectQualityInfo60C::longitude_accel_rms(const std::uint8_t* bytes,
                                              int32_t length) const {
  Byte t0(bytes + 3);
  int32_t x = t0.get_byte(0, 4);

  Byte t1(bytes + 4);
  int32_t t = t1.get_byte(7, 1);

  x <<= 1;
  x |= t;

  int ret = x;
  return ret;
}

int ObjectQualityInfo60C::lateral_accel_rms(const std::uint8_t* bytes,
                                            int32_t length) const {
  Byte t0(bytes + 4);
  int32_t x = t0.get_byte(2, 5);

  int ret = x;
  return ret;
}

int ObjectQualityInfo60C::oritation_angle_rms(const std::uint8_t* bytes,
                                              int32_t length) const {
  Byte t0(bytes + 4);
  int32_t x = t0.get_byte(0, 2);

  Byte t1(bytes + 5);
  int32_t t = t1.get_byte(5, 3);

  x <<= 3;
  x |= t;

  int ret = x;
  return ret;
}

int ObjectQualityInfo60C::probexist(const std::uint8_t* bytes,
                                    int32_t length) const {
  Byte t0(bytes + 6);
  int32_t x = t0.get_byte(5, 3);

  int ret = x;
  return ret;
}

int ObjectQualityInfo60C::meas_state(const std::uint8_t* bytes,
                                     int32_t length) const {
  Byte t0(bytes + 6);
  int32_t x = t0.get_byte(2, 3);

  int ret = x;
  return ret;

