 double weight_rate_steer_ = 0.0;
 double weight_rate_a_ = 0.0;
 double weight_stitching_steer_ = 0.0;
 double weight_stitching_a_ = 0.0;
 double weight_first_order_time_ = 0.0;
 double weight_second_order_time_ = 0.0;

 double w_ev_ = 0.0;
